#include <stdint.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>
#include <openssl/opensslconf.h>

int FuzzerInitialize(int *argc, char ***argv);
int FuzzerTestOneInput(const uint8_t *buf, size_t len);
void FuzzerCleanup(void);

int main(int argc, char** argv)
{
    uint8_t *buf;
    size_t size;
    FILE *f;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }

    FuzzerInitialize(&argc, &argv);

    f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }
    fseek(f, 0, SEEK_END);
    size = ftell(f);
    fseek(f, 0, SEEK_SET);
    buf = malloc(size);
    fread(buf, 1, size, f);
    fclose(f);

    FuzzerTestOneInput(buf, size);
    free(buf);
    FuzzerCleanup();
    return 0;
}
EOF
